    30	import javax.annotation.Nullable;
    31	import java.lang.reflect.Member;
    32	import java.util.Objects;
    33	import java.util.function.UnaryOperator;
    34	
    35	/**
    36	 * Expression holder
    37	 *
    38	 * Internally keeps two expressions {@code current} and {@code partial} which
    39	 * are combined using different functions depending on current context.
    40	 */
    41	public final class CriteriaContext implements Queryable {
    42	
    43	  /**
    44	   * Singleton which stores class metadata for faster lookups
    45	   */
    46	  private static final MemberLookupCache MEMBER_LOOKUP_SINGLETON = new MemberLookupCache();
    47	
    48	  private final CriteriaContext previous;
    49	  private final ImmutableState state;
    50	  private final MemberLookupCache memberLookup;
    51	
    52	  public CriteriaContext(Class<?> entityType, CriteriaCreator<?> creator) {
    53	    this(null,
    54	            ImmutableState.builder()
    55	                    .combiner(Combiner.and())
    56	                    .creator(creator)
    57	                    .entityType(entityType)
    58	                    .build()
    59	    );
    60	  }
    61	
    62	  CriteriaContext(CriteriaContext previous, ImmutableState state) {
    63	    this.previous = previous;
    64	    this.state = Objects.requireNonNull(state, "state");
    65	    this.memberLookup = MEMBER_LOOKUP_SINGLETON;
    66	  }
    67	
    68	  @Value.Immutable
    69	  interface State {
    70	    @Nullable Expression current();
    71	    @Nullable Expression partial();
    72	    Combiner combiner();
    73	    CriteriaCreator<?> creator();
    74	    Class<?> entityType();
    75	
    76	    @Value.Default
    77	    @Nullable
    78	    default Expression defaultPartial() {
    79	      return null;
    80	    }
    81	  }
    82	
    83	  public Path path() {
    84	    return Visitors.toPath(state.partial());
    85	  }
    86	
    87	  ImmutableState state() {
    88	    return state;
    89	  }
    90	
    91	  public Expression expression() {
    92	    if (state.current() != null) {
    93	      return state.current();
    94	    }
    95	
    96	    return state.partial();
    97	  }
    98	
    99	  private CriteriaContext first() {
   100	    return previous != null ? previous.first() : this;
   101	  }
   102	
   103	  @SuppressWarnings("unchecked")
   104	  <R> R create() {
   105	    return (R) createWith(state.creator());
   106	  }
   107	
   108	  @SuppressWarnings("unchecked")
   109	  <R> CriteriaCreator<R> creator() {
   110	    return (CriteriaCreator<R>) state.creator();
   111	  }
   112	
   113	  /**
   114	   *  adds an intermediate path to partial expression
   115	   */
   116	  public <T> CriteriaContext appendPath(Class<?> type, String pathAsString, CriteriaCreator<T> creator) {
   117	    final Member member = memberLookup.find(type, pathAsString)
   118	            .orElseThrow(() -> new IllegalArgumentException(String.format("Path %s not found in %s", pathAsString, type)));
   119	
   120	    Path newPath;
   121	    Expression partial = state.partial();
   122	    if (partial == null) {
   123	      newPath = Path.ofMember(member);
   124	    } else if (partial instanceof Path) {
   125	      newPath = Visitors.toPath(partial).append(member);
   126	    } else {
   127	      throw new IllegalStateException("Partial expression is not a path: " + partial);
   128	    }
   129	
   130	    return new CriteriaContext(this, state.withPartial(newPath).withCreator(creator));
   131	  }
   132	
   133	  /**
   134	   * Create nested context for lambdas used in {@link WithMatcher} or {@link NotMatcher}.
   135	   * It is considered new root expression
   136	   */
   137	  CriteriaContext nested() {
   138	    // return new CriteriaContext(entityClass, new DnfExpression(), path, creator, null);
   139	    ImmutableState newState = state.withCurrent(null).withDefaultPartial(state.partial()).withCombiner(Combiner.dnfAnd());
   140	    return new CriteriaContext(null, newState);
   141	  }
   142	
   143	  public CriteriaContext or() {
   144	    return new CriteriaContext(previous, state.withCombiner(Combiner.or()));
   145	  }
   146	
   147	  /**
   148	   * Build {@link IterableMatcher#any()} sub-matcher.
   149	   */
   150	  public CriteriaContext any() {
   151	    Path path = path();
   152	    Class<?> newType; // new path starts at this root
   153	    try {
   154	      newType = (Class<?>) Matchers.iterableTypeArgument(path.returnType());
   155	    } catch (IllegalArgumentException|ClassCastException e) {
   156	      throw new IllegalArgumentException(String.format("At path %s for %s",
   157	              path.toStringPath(), path.returnType()), e);
   158	    }
   159	
   160	    Path newPath = Path.ofClass(newType);
   161	    Combiner combiner = ((left, right) -> Expressions.binaryCall(IterableOperators.ANY, path, right));
   162	    return new CriteriaContext(previous, state.withCombiner(combiner).withPartial(newPath));
   163	  }
   164	
   165	  @Override
   166	  public Query query() {
   167	    ImmutableQuery query = Query.of(state.entityType());
   168	    if (state.current() != null) {
   169	      query = query.withFilter(state.current());
   170	    }
   171	    return query;
   172	  }
   173	
   174	  <R> R createWith(CriteriaCreator<R> creator) {
   175	    return creator.create(this);
   176	  }
   177	
   178	  /**
   179	   * Used by Aggregator Matchers (sum / count / avg etc.)
   180	   */
   181	  CriteriaContext applyRaw(UnaryOperator<Expression> fn) {
   182	    return new CriteriaContext(previous, state.withPartial(fn.apply(state.partial())));
   183	  }
   184	
   185	  <R> R applyAndCreateRoot(UnaryOperator<Expression> fn, Combiner nextCombiner) {
   186	    Expression newPartial = fn.apply(state.partial());
   187	    Expression newExpression = state.combiner().combine(state.current(), newPartial);
   188	    newPartial = newExpression;
   189	    CriteriaContext context = this.previous;
   190	
   191	    while (context != null) {
   192	      Expression tmpExpression = context.state.combiner().combine(context.state.current(), newPartial);
   193	      if (isPathExtention(tmpExpression, newExpression)) {
   194	        newExpression = tmpExpression;
   195	        newPartial = tmpExpression;
   196	      }
   197	
   198	      context = context.previous;
   199	    }
   200	    
   201	    // use initial creator
   202	    CriteriaCreator<?> creator = first().state.creator();
   203	
   204	    ImmutableState newState = state.withCombiner(nextCombiner)
   205	            .withCreator(creator)
   206	            .withCurrent(newExpression)
   207	            .withPartial(state.defaultPartial());
   208	
   209	    return new CriteriaContext(null, newState).create();
   210	  }
   211	
   212	  <R> R applyAndCreateRoot(UnaryOperator<Expression> fn) {
   213	    return applyAndCreateRoot(fn, Combiner.dnfAnd());
   214	  }
   215	
   216	  private static boolean isPathExtention(Expression newExpression, Expression expression) {
   217	    if (newExpression instanceof Call && expression instanceof Call) {
   218	      return !((Call) newExpression).arguments().get(0).equals(((Call) expression).arguments().get(0));
   219	    } else {
   220	      return true;
   221	    }
   222	  }
   223	}

