    30	import org.immutables.criteria.backend.PathNaming;
    31	import org.immutables.criteria.expression.AbstractExpressionVisitor;
    32	import org.immutables.criteria.expression.Call;
    33	import org.immutables.criteria.expression.ComparableOperators;
    34	import org.immutables.criteria.expression.Constant;
    35	import org.immutables.criteria.expression.Expression;
    36	import org.immutables.criteria.expression.Expressions;
    37	import org.immutables.criteria.expression.IterableOperators;
    38	import org.immutables.criteria.expression.Operator;
    39	import org.immutables.criteria.expression.Operators;
    40	import org.immutables.criteria.expression.OptionalOperators;
    41	import org.immutables.criteria.expression.Path;
    42	import org.immutables.criteria.expression.StringOperators;
    43	import org.immutables.criteria.expression.Visitors;
    44	
    45	import java.util.ArrayList;
    46	import java.util.Collection;
    47	import java.util.Collections;
    48	import java.util.List;
    49	import java.util.Objects;
    50	import java.util.regex.Pattern;
    51	import java.util.stream.Collectors;
    52	
    53	/**
    54	 * Converts find expression to Mongo BSON format
    55	 * @see <a href="https://docs.mongodb.com/manual/tutorial/query-documents/">Query Documents</a>
    56	 */
    57	class FindVisitor extends AbstractExpressionVisitor<Bson> {
    58	
    59	  private final PathNaming naming;
    60	  private final CodecRegistry codecRegistry;
    61	
    62	  FindVisitor(PathNaming pathNaming, CodecRegistry codecRegistry) {
    63	    super(e -> { throw new UnsupportedOperationException(); });
    64	    this.naming = Objects.requireNonNull(pathNaming, "pathNaming");
    65	    this.codecRegistry = Objects.requireNonNull(codecRegistry, "codecRegistry");
    66	  }
    67	
    68	  // Construct field name which is derived expression (which is expected to be a Path).
    69	  private String fieldName(Expression expression) {
    70	    return naming.name(Visitors.toPath(expression));
    71	  }
    72	
    73	  @Override
    74	  public Bson visit(Call call) {
    75	    final Operator op = call.operator();
    76	    final List<Expression> args = call.arguments();
    77	
    78	
    79	    if (op == OptionalOperators.IS_ABSENT || op == OptionalOperators.IS_PRESENT) {
    80	      Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
    81	      final String field = fieldName(args.get(0));
    82	      Bson filter;
    83	      if (op == OptionalOperators.IS_PRESENT) {
    84	        filter = Filters.and(Filters.exists(field), Filters.ne(field, null));
    85	      } else {
    86	        // absent fields means null or missing
    87	        filter = Filters.or(Filters.exists(field, false), Filters.eq(field, null));
    88	      }
    89	      return filter;
    90	    }
    91	
    92	    if (op == Operators.AND || op == Operators.OR) {
    93	      final List<Bson> list = call.arguments().stream()
    94	              .map(a -> a.accept(this))
    95	              .collect(Collectors.toList());
    96	
    97	      return op == Operators.AND ? Filters.and(list) : Filters.or(list);
    98	    }
    99	
   100	    if (op == Operators.NOT) {
   101	      return this.negate(args.get(0));
   102	    }
   103	
   104	    if (op == IterableOperators.IS_EMPTY || op == IterableOperators.NOT_EMPTY) {
   105	      Preconditions.checkArgument(args.size() == 1, "Size should be 1 for %s but was %s", op, args.size());
   106	      final String field = fieldName(args.get(0));
   107	      return op == IterableOperators.IS_EMPTY ? Filters.eq(field, Collections.emptyList())
   108	              : Filters.and(Filters.exists(field), Filters.ne(field, null), Filters.ne(field, Collections.emptyList()));
   109	    }
   110	    
   111	    if (op == IterableOperators.ANY) {
   112	      Call rightCall = call;
   113	      Path path = null;
   114	
   115	      while (rightCall.operator() == IterableOperators.ANY) {
   116	        Preconditions.checkArgument(rightCall.arguments().size() == 2, "Expected two arguments for %s got %s", rightCall, rightCall.arguments().size());
   117	        Preconditions.checkArgument(rightCall.arguments().get(0) instanceof Path, "%s is not a path", rightCall.arguments().get(0));
   118	        Preconditions.checkArgument(rightCall.arguments().get(1) instanceof Call, "%s is not a call", rightCall.arguments().get(1));
   119	
   120	        Path subPath = (Path) rightCall.arguments().get(0);
   121	        if (path != null) {
   122	          for (java.lang.reflect.Member member : subPath.members()) {
   123	            path = path.append(member);
   124	          }
   125	        } else {
   126	          path = subPath;
   127	        }
   128	        rightCall = (Call) rightCall.arguments().get(1);
   129	      }
   130	
   131	      // Handle AND/OR/NOT operators within ANY (for compound conditions on array elements).
   132	      // Also use $elemMatch for NOT_EQUAL and NOT_IN: flat dot-path $ne/$nin means "no element
   133	      // matches" (universal), but any().isNot/notIn requires existential ("at least one element").
   134	      if (rightCall.operator() == Operators.AND ||
   135	          rightCall.operator() == Operators.OR ||
   136	          rightCall.operator() == Operators.NOT ||
   137	          rightCall.operator() == Operators.NOT_EQUAL ||
   138	          rightCall.operator() == Operators.NOT_IN) {
   139	        final String arrayField = fieldName(path);
   140	        Bson condition = this.buildElemMatchCondition(rightCall);
   141	        return Filters.elemMatch(arrayField, condition);
   142	      }
   143	
   144	      // Handle simple comparison operators within ANY
   145	      Preconditions.checkArgument(rightCall.arguments().get(0) instanceof Path,"%s is not a path", rightCall.arguments().get(0));
   146	
   147	      // Reconstruct the full path by combining the array path with the condition path
   148	      Path currentPath = Visitors.toPath(rightCall.arguments().get(0));
   149	      List<Path> paths = new ArrayList<>();
   150	      while (currentPath.parent().isPresent()) {
   151	        paths.add(currentPath);
   152	        currentPath = currentPath.parent().get();
   153	      }
   154	      Collections.reverse(paths);
   155	      for (Path tmpPath : paths) {
   156	        path = Path.combine(path, tmpPath);
   157	      }
   158	
   159	      return this.buildCondition(rightCall, rightCall.operator(), path);
   160	    }
   161	
   162	    if (op.arity() == Operator.Arity.BINARY) {
   163	      return this.binaryCall(call);
   164	    }
   165	
   166	
   167	    throw new UnsupportedOperationException(String.format("Not yet supported (%s): %s", call.operator(), call));
   168	  }
   169	
   170	  private Bson binaryCall(Call call) {
   171	    Preconditions.checkArgument(call.operator().arity() == Operator.Arity.BINARY, "%s is not binary", call.operator());
   172	    final Operator op = call.operator();
   173	    Expression left = call.arguments().get(0);
   174	    Expression right = call.arguments().get(1);
   175	
   176	    if (!(left instanceof Path && right instanceof Constant)) {
   177	      // special case when $expr has to be used
   178	      return call.accept(new MongoExpr(this.naming, this.codecRegistry)).asDocument();
   179	    }
   180	
   181	    final String field = fieldName(left);
   182	    final Object value = Visitors.toConstant(right).value();
   183	    if (op == Operators.EQUAL || op == Operators.NOT_EQUAL) {
   184	      if ("".equals(value) && op == Operators.NOT_EQUAL) {
   185	        // special case for empty string. string != "" should not return missing strings
   186	        return Filters.and(Filters.nin(field, value, null), Filters.exists(field));
   187	      }
   188	      return op == Operators.EQUAL ? Filters.eq(field, value) : Filters.ne(field, value);
   189	    }
   190	
   191	    if (ComparableOperators.isComparable(op)) {
   192	      if (op == ComparableOperators.GREATER_THAN) {
   193	        return Filters.gt(field, value);
   194	      } else if (op == ComparableOperators.GREATER_THAN_OR_EQUAL) {
   195	        return Filters.gte(field, value);
   196	      } else if (op == ComparableOperators.LESS_THAN) {
   197	        return Filters.lt(field, value);
   198	      } else if (op == ComparableOperators.LESS_THAN_OR_EQUAL) {
   199	        return Filters.lte(field, value);
   200	      }
   201	
   202	      throw new UnsupportedOperationException("Unknown comparison " + call);
   203	    }
   204	
   205	    if (op == Operators.IN || op == Operators.NOT_IN) {
   206	      final Collection<Object> values = ImmutableSet.copyOf(Visitors.toConstant(right).values());
   207	      Preconditions.checkNotNull(values, "not expected to be null for %s", op);
   208	      if (values.size() == 1) {
   209	        // optimization: convert IN, NIN (where argument is a list with single element) into EQ / NE
   210	        Operators newOperator = op == Operators.IN ? Operators.EQUAL : Operators.NOT_EQUAL;
   211	        Call newCall = Expressions.binaryCall(newOperator, left, Expressions.constant(values.iterator().next()));
   212	        return this.binaryCall(newCall);
   213	      }
   214	      return op == Operators.IN ? Filters.in(field, values) : Filters.nin(field, values);
   215	    }
   216	
   217	    if (op == StringOperators.MATCHES || op == StringOperators.CONTAINS) {
   218	      Object newValue = value;
   219	      if (op == StringOperators.CONTAINS) {
   220	        // handle special case for string contains with regexp
   221	        newValue = Pattern.compile(".*" + Pattern.quote(value.toString()) + ".*");
   222	      }
   223	      Preconditions.checkArgument(newValue instanceof Pattern, "%s is not regex pattern", value);
   224	      return Filters.regex(field, (Pattern) newValue);
   225	    }
   226	
   227	    if (op == IterableOperators.HAS_SIZE) {
   228	      Preconditions.checkArgument(value instanceof Number, "%s is not a number", value);
   229	      int size = ((Number) value).intValue();
   230	      return Filters.size(field, size);
   231	    }
   232	
   233	    if (op == IterableOperators.CONTAINS) {
   234	      return Filters.eq(field, value);
   235	    }
   236	
   237	    if (op == StringOperators.HAS_LENGTH) {
   238	      Preconditions.checkArgument(value instanceof Number, "%s is not a number", value);
   239	      final int length = ((Number) value).intValue();
   240	      // use strLenCP function
   241	      // https://docs.mongodb.com/manual/reference/operator/aggregation/strLenCP/#exp._S_strLenCP
   242	      final Bson lengthExpr  = Document.parse(String.format("{$expr:{$eq:[{$strLenCP: \"$%s\"}, %d]}}}", field, length));
   243	      // field should exists and not be null
   244	      return Filters.and(Filters.exists(field), Filters.ne(field, null), lengthExpr);
   245	    }
   246	
   247	    if (op == StringOperators.STARTS_WITH || op == StringOperators.ENDS_WITH) {
   248	      // regular expression
   249	      final String pattern = String.format("%s%s%s",
   250	              op == StringOperators.STARTS_WITH ? "^": "",
   251	              Pattern.quote(value.toString()),
   252	              op == StringOperators.ENDS_WITH ? "$" : "");
   253	      return Filters.regex(field, Pattern.compile(pattern));
   254	    }
   255	
   256	
   257	    throw new UnsupportedOperationException(String.format("Unsupported binary call %s", call));
   258	  }
   259	
   260	  /**
   261	   * see <a href="https://docs.mongodb.com/manual/reference/operator/query/not/">mongo query manual $not</a>
   262	   * NOT operator is mongo is a little specific and can't be applied on all levels
   263	   * $not: { $or ... } will not work and should be transformed to $nor
   264	   */
   265	  private Bson negate(Expression expression) {
   266	    if (!(expression instanceof Call)) {
   267	      return Filters.not(expression.accept(this));
   268	    }
   269	
   270	    Call notCall = (Call) expression;
   271	    Operator notOperator = notCall.operator();
   272	
   273	    if (notOperator == Operators.NOT) {
   274	      // NOT NOT a == a
   275	      return notCall.arguments().get(0).accept(this);
   276	    } else if (notOperator == Operators.EQUAL) {
