#!/usr/bin/env python3
import pathlib, sys
text=sys.stdin.read()
assert text.startswith('*** Begin Patch\n') and text.rstrip().endswith('*** End Patch')
body=text[len('*** Begin Patch\n'):body_end] if False else text[len('*** Begin Patch\n'):text.rfind('*** End Patch')]
lines=body.splitlines(True); i=0
while i < len(lines):
    assert lines[i].startswith('*** Update File: '), lines[i]
    path=pathlib.Path(lines[i][len('*** Update File: '):].strip()); i+=1
    original=path.read_text(); updated=original
    while i < len(lines) and not lines[i].startswith('*** Update File: '):
        if lines[i].startswith('@@'):
            i+=1; old=[]; new=[]
            while i < len(lines) and not lines[i].startswith('@@') and not lines[i].startswith('*** Update File: '):
                line=lines[i]
                if line.startswith(' '): old.append(line[1:]); new.append(line[1:])
                elif line.startswith('-'): old.append(line[1:])
                elif line.startswith('+'): new.append(line[1:])
                else: raise SystemExit('bad hunk line '+repr(line))
                i+=1
            old_text=''.join(old); new_text=''.join(new)
            count=updated.count(old_text)
            if count != 1: raise SystemExit(f'{path}: hunk occurrence count {count}\n{old_text}')
            updated=updated.replace(old_text,new_text,1)
        elif lines[i].strip(): raise SystemExit('bad directive '+lines[i])
        else: i+=1
    path.write_text(updated)
